#!/usr/bin/env python3
"""Generate the Taylor-typed pointwise constraint/psi4 algebra from the production generated file src/physconeqs.cpp.
usage: gen_taylor_psi4.py <src/physconeqs.cpp> <outdir>   -> taylor_psi4_point.inc, taylor_psi4_names.inc"""
import re, sys
eq, outdir = sys.argv[1:3]
FIELDS = {'alpha': 'U_ALPHA', 'chi': 'U_CHI', 'K': 'U_K', **{f'gt{i}': f'U_SYMGT{i}' for i in range(6)}, **{f'beta{i}': f'U_BETA{i}' for i in range(3)},
          **{f'At{i}': f'U_SYMAT{i}' for i in range(6)}, **{f'Gt{i}': f'U_GT{i}' for i in range(3)}, **{f'B{i}': f'U_B{i}' for i in range(3)}}
OUTS = ['ham', 'mom0', 'mom1', 'mom2', 'psi4_real', 'psi4_img']
body, inputs = [], set()
for line in open(eq).read().splitlines():
    s = line.strip()
    if not s or s.startswith('//'): continue
    m = re.match(r'^(\w+)\[pp\]\s*=\s*(.*)$', s)
    if m and m.group(1) in OUTS:
        s2 = f'OUT_{m.group(1)} = ' + m.group(2)
    else:
        s2 = re.sub(r'^const double (DENDRO_\w+)\s*=', r'const T \1 =', s)
    for n in re.findall(r'\b(\w+)\[pp\]', s2): inputs.add(n)
    s2 = re.sub(r'\b(\w+)\[pp\]', r'\1_T', s2)
    body.append(s2)
fu = sorted(n for n in inputs if n in FIELDS); du = sorted(n for n in inputs if n not in FIELDS)
assert all(n.startswith('grad') for n in du), [n for n in du if not n.startswith('grad')]
open(f'{outdir}/taylor_psi4_point.inc', 'w').write('// GENERATED by gen_taylor_psi4.py: do not edit\n' + '\n'.join(body) + '\n')
with open(f'{outdir}/taylor_psi4_names.inc', 'w') as f:
    f.write('#define PSI_FIELD_USED(X) \\\n' + ' \\\n'.join(f'  X({n}, {FIELDS[n]})' for n in fu) + '\n')
    f.write('#define PSI_DERIV_NAMES(X) \\\n' + ' \\\n'.join(f'  X({n})' for n in du) + '\n')
    f.write('#define PSI_OUT_NAMES(X) \\\n' + ' \\\n'.join(f'  X({n})' for n in OUTS) + '\n')
print(len(body), 'statements;', len(fu), 'fields;', len(du), 'derivative inputs')
